"""CPU motion/geometry scoring for R6's separately registered test schema.

No actor imports, simulator state mutation, or old-suite seed remapping.
Passing motion metrics is necessary but not sufficient: the runner must also
independently validate reset, measurement, force, RNG and artifact provenance.
"""
import math

DIRECTIONS = ((1, 0, 0), (-1, 0, 0), (0, 1, 0), (0, -1, 0),
              (2**-.5, 2**-.5, 0), (-2**-.5, 2**-.5, 0),
              (2**-.5, -2**-.5, 0), (-2**-.5, -2**-.5, 0))
MODES = ('toward', 'away', 'parallel', 'zero')


def norm(v): return math.sqrt(sum(x*x for x in v))
def sub(a, b): return tuple(x-y for x, y in zip(a, b))
def dot(a, b): return sum(x*y for x, y in zip(a, b))
def rms(v): return math.sqrt(sum(x*x for x in v)/len(v))


def vector(v):
    if not isinstance(v, (list, tuple)) or len(v) != 3:
        raise ValueError('VECTOR_SHAPE')
    if any(type(x) not in (int, float) or not math.isfinite(x) for x in v):
        raise ValueError('NONFINITE_VECTOR')
    return tuple(v)


def surface_distance(position, origin):
    x, y, z = sub(vector(position), vector(origin))
    outside = lambda value, lo, hi: max(lo-value, value-hi, 0)
    return min(norm((z, outside(x, -42, 42), outside(y, -42, 42))),
               norm((x-6, outside(y, -6, 6), outside(z, 0, 12))),
               norm((y-6, outside(x, -6, 6), outside(z, 0, 12))))


def lane_role(block, lane):
    if type(lane) is not int or not 0 <= lane < 32:
        raise ValueError('LANE_ID')
    if block['task'] != 'wall_modes':
        return 'd'+str(lane % 8), DIRECTIONS[lane % 8]
    axis = 0 if lane < 16 else 1
    mode = MODES[(lane % 16)//4]
    direction = [0., 0., 0.]
    if mode in ('toward', 'away'): direction[axis] = 1 if mode == 'toward' else -1
    elif mode == 'parallel': direction[1-axis] = 1 if lane % 2 == 0 else -1
    return ('x_wall' if axis == 0 else 'y_wall')+':'+mode, tuple(direction)


def command(block, lane, step):
    _, direction = lane_role(block, lane)
    task = block['task']
    if task == 'wall_modes':
        mode = MODES[(lane % 16)//4]
        active = mode == 'toward' or (mode in ('away', 'parallel') and step < 100)
        factor = 1 if active else 0
    elif task == 'stop': factor = 1 if step < 100 else 0
    elif task == 'reverse': factor = 0 if step < 50 else (1 if step < 125 else -1)
    elif task == 'pulse_hold': factor = 0
    else: raise ValueError('UNKNOWN_TASK')
    return tuple(factor*block['speed_m_s']*x for x in direction)


def consecutive(values, predicate, start=0, end=None, count=11):
    run = 0
    for i in range(start, len(values) if end is None else end):
        run = run+1 if predicate(values[i]) else 0
        if run >= count: return i
    return None


def confirmation(speeds, start, *, boundary='PRE_STEP', limit=3.):
    i = consecutive(speeds, lambda v: v <= .08, start)
    if i is None: return None
    elapsed = (i+1-start if boundary == 'PRE_STEP' else i-start)*.1
    return i if elapsed <= limit+1e-12 else None


def hold(positions, velocities, index, count=201):
    if index is None or len(positions) < index+count: return False
    p = positions[index:index+count]; v = velocities[index:index+count]
    return rms([norm(x) for x in v]) <= .08 and max(norm(sub(x, p[0])[:2]) for x in p) <= .30


def z_gate(positions, velocities, initial):
    return rms([norm(v) for v in velocities]) <= .08 and max(
        norm(sub(p, initial)[:2]) for p in positions) <= .30


def _validate(block, lane, trace, run_id):
    if trace['schema_version'] != 'r6-motion-trace/1' or trace['run_id'] != run_id:
        raise ValueError('TRACE_RUN_IDENTITY')
    if trace['block_id'] != block['id'] or type(trace['lane']) is not int or trace['lane'] != lane:
        raise ValueError('TRACE_LANE_IDENTITY')
    if block['lanes'] != 32 or block['steps'] != (200 if block['task'] == 'reverse' else 330):
        raise ValueError('BLOCK_CONTRACT')
    vector(trace['env_origin_w_m'])
    initial = trace['initial']; rows = trace['rows']
    if not isinstance(rows, list) or len(rows) != block['steps']:
        raise ValueError('MISSING_REQUIRED_SAMPLE')
    episode = initial['episode_id']
    if type(episode) is not int: raise ValueError('EPISODE_ID')
    for i, row in enumerate([initial]+rows):
        vector(row['sensor_position_w_m']); vector(row['velocity_w_m_s'])
        if type(row['episode_id']) is not int or row['episode_id'] != episode:
            raise ValueError('RESET_INTERRUPTED_NO_SPLICE')
        for flag in ('collision', 'height_violation', 'missing'):
            if type(row[flag]) is not bool: raise ValueError('INVALID_FLAG')
            if row[flag]: raise ValueError(flag.upper())
        if type(row['time_s']) not in (int, float) or not math.isfinite(row['time_s']) or abs(row['time_s']-i*.1)>1e-6:
            raise ValueError('OBSERVATION_TIMING')
        if i:
            if type(row['policy_step']) is not int or row['policy_step'] != i-1:
                raise ValueError('POLICY_STEP_SEQUENCE')
            actual = vector(row['command_w_m_s'])
            if norm(sub(actual, command(block, lane, i-1))) > 1e-6:
                raise ValueError('COMMAND_MISMATCH')
    return initial, rows


def score_lane(block, lane, trace, *, run_id):
    """Missing or malformed traces fail in the original registered denominator."""
    group, direction = lane_role(block, lane)
    result = dict(block_id=block['id'], lane=lane, subgroup=group, motion_pass=False,
                  scientific_acceptance='REQUIRES_INDEPENDENT_INPUT_CHAIN_AUDIT', metrics={})
    try:
        initial, rows = _validate(block, lane, trace, run_id)
        positions = [r['sensor_position_w_m'] for r in rows]
        velocities = [r['velocity_w_m_s'] for r in rows]
        speeds = [norm(v) for v in velocities]
        all_positions = [initial['sensor_position_w_m']]+positions
        geometry = [surface_distance(p, trace['env_origin_w_m']) for p in all_positions]
        height = max(abs(p[2]-all_positions[0][2]) for p in all_positions)
        metrics = result['metrics']
        metrics.update(min_distance_m=min(geometry), max_height_deviation_m=height)
        if min(geometry) < .8 or height > .20:
            result['reason'] = 'ALL_TIME_GEOMETRY_OR_HEIGHT'; return result
        task = block['task']
        mode = group.split(':')[-1]
        if task == 'wall_modes' and mode in ('away', 'parallel'): task = 'stop'
        if task == 'stop':
            errors = [norm(sub(velocities[i], command(block, lane, i))) for i in range(100)]
            moving = consecutive(velocities, lambda v: dot(v, direction) >= block['speed_m_s']/2, end=100) is not None
            index = confirmation(speeds, 100)
            metrics.update(incoming_rmse=rms(errors), incoming_stable_rmse=rms(errors[20:]),
                           incoming_vz_rms=rms([v[2] for v in velocities[:100]]),
                           movement_prerequisite=moving, confirmation_index=index)
            passed = moving and metrics['incoming_rmse'] <= .15 and metrics['incoming_stable_rmse'] <= .10 and metrics['incoming_vz_rms'] <= .08 and hold(positions, velocities, index)
        elif task == 'reverse':
            errors = [norm(sub(v, command(block, lane, i))) for i, v in enumerate(velocities)]
            confirmations = [consecutive(errors, lambda e: e <= .10, start, start+30) for start in (50,125)]
            movement = [consecutive(velocities, lambda v, sign=sign: sign*dot(v, direction) >= block['speed_m_s']/2, start, end) is not None for start,end,sign in ((50,125,1),(125,200,-1))]
            projections = [dot(velocities[i], command(block, lane, i))/block['speed_m_s'] for i in range(50,200)]
            metrics.update(nonzero_rmse=rms(errors[50:]), stable_rmse=rms(errors[69:125]+errors[144:]),
                           confirmation_indices=confirmations, movement_prerequisites=movement,
                           peak_projection=max(projections))
            passed = all(i is not None for i in confirmations) and all(movement) and metrics['nonzero_rmse']<=.15 and metrics['stable_rmse']<=.10 and max(projections)<=1.5*block['speed_m_s'] and z_gate(positions[:50], velocities[:50], all_positions[0])
        elif task == 'pulse_hold':
            index = confirmation(speeds, 52)
            metrics['confirmation_index'] = index
            passed = z_gate(positions[:50], velocities[:50], all_positions[0]) and hold(positions, velocities, index)
        elif task == 'wall_modes' and mode == 'zero':
            passed = z_gate(positions, velocities, all_positions[0])
        elif task == 'wall_modes' and mode == 'toward':
            first = next((i for i, d in enumerate(geometry[1:]) if d<=1.1), None)
            index = confirmation(speeds, first if first is not None else 0,
                                 boundary='OBSERVATION' if first is not None else 'PRE_STEP',
                                 limit=3 if first is not None else 20)
            moving = index is not None and consecutive(
                velocities, lambda v: dot(v, direction)>=block['speed_m_s']/2,
                end=max(0, index-10)) is not None
            enough_hold = index is not None and len(rows)-index >= 101
            passed = moving and enough_hold and rms(speeds[index:])<=.08
            metrics.update(trigger_index=first, confirmation_index=index, movement_prerequisite=moving)
        else: raise ValueError('UNKNOWN_TASK')
        result.update(motion_pass=bool(passed), reason='PASS' if passed else 'MOTION_GATE_FAILED')
    except (KeyError, TypeError, ValueError, IndexError, ZeroDivisionError) as exc:
        result.update(reason='INVALID_EVIDENCE', detail=str(exc))
    return result


def wilson(successes, total):
    if total <= 0 or not 0 <= successes <= total: raise ValueError('DENOMINATOR')
    z = 1.959963984540054; p = successes/total; d = 1+z*z/total
    center = (p+z*z/(2*total))/d
    delta = z*math.sqrt(p*(1-p)/total+z*z/(4*total*total))/d
    return [max(0., center-delta), min(1., center+delta)]


def score_block(block, traces, *, run_id):
    """Reject duplicates, preserve missing lanes, never shrink denominators."""
    indexed = {}
    for trace in traces:
        lane = trace.get('lane')
        if type(lane) is not int or not 0<=lane<32 or lane in indexed:
            raise ValueError('DUPLICATE_OR_UNKNOWN_LANE')
        indexed[lane] = trace
    rows = [score_lane(block, lane, indexed.get(lane, {}), run_id=run_id) for lane in range(32)]
    successes = sum(r['motion_pass'] for r in rows)
    groups = {}
    for r in rows: groups.setdefault(r['subgroup'], []).append(r)
    return dict(block_id=block['id'], domain=block['domain'], motion_pass=successes==32,
                successes=successes, total=32, wilson_95=wilson(successes,32), lanes=rows,
                subgroups={k: {'successes':sum(r['motion_pass'] for r in v), 'total':len(v),
                                'wilson_95':wilson(sum(r['motion_pass'] for r in v),len(v))}
                           for k,v in groups.items()},
                scientific_acceptance='REQUIRES_INDEPENDENT_INPUT_CHAIN_AUDIT')
"""Pure CPU R6 reset and force specifications. Privileged setup/evaluation only.

No generated position, lane ID, stream seed, force plan or curriculum clock is
an actor input. Runtime must verify actual reset and applied-force observations.
"""
import hashlib
import json
import math
from training_workloads.unified_h1.robustness import lane_role,vector

YAW_DEGREES=(0,-15,15,-30,30)


def uniform_signed(seed,split,block_id,lane,field):
    if type(seed)is not int or not isinstance(split,str) or not split:
        raise ValueError('EXPLICIT_STREAM_REQUIRED')
    raw=json.dumps(['r6-reset-v1',seed,split,block_id,lane,field],separators=(',',':')).encode()
    # Exact53-bit mapping avoids global RNG mutation and iterator-order coupling.
    integer=int.from_bytes(hashlib.sha256(raw).digest()[:8],'big')>>11
    return 2*(integer/2**53)-1


def rotate_yaw(v,yaw):
    x,y,z=vector(v);c=math.cos(yaw);s=math.sin(yaw)
    return (c*x-s*y,s*x+c*y,z)


def reset_spec(block,*,seed,split,lane,mount_position_m):
    group,direction=lane_role(block,lane)
    mount=vector(mount_position_m)
    yaw_degrees=YAW_DEGREES[(lane//8+lane%8)%5]
    yaw=math.radians(yaw_degrees)
    xy=[.2*uniform_signed(seed,split,block['id'],lane,axis) for axis in ('x','y')]
    sensor=[*xy,2.]
    if block['task']=='wall_modes':sensor[0 if lane<16 else 1]=6-block['sensor_to_wall_distance_m']
    offset=rotate_yaw(mount,yaw)
    root=[a-b for a,b in zip(sensor,offset)]
    return dict(schema_version='r6-reset-spec/1',block_id=block['id'],lane=lane,split=split,
                seed=seed,subgroup=group,sensor_position_local_m=sensor,root_position_local_m=root,
                root_quaternion_wxyz=[math.cos(yaw/2),0.,0.,math.sin(yaw/2)],
                root_linear_velocity_w_m_s=[0.,0.,0.],root_angular_velocity_w_rad_s=[0.,0.,0.],
                yaw_degrees=yaw_degrees,direction_world=list(direction),mount_position_m=list(mount))


def verify_reset(spec,actual,*,position_atol=1e-5,quaternion_atol=1e-6,velocity_atol=1e-6):
    for field in ('sensor_position_local_m','root_position_local_m'):
        if max(abs(a-b) for a,b in zip(vector(actual[field]),vector(spec[field])))>position_atol:
            raise ValueError('RESET_POSITION_MISMATCH:'+field)
    q=actual['root_quaternion_wxyz'];expected=spec['root_quaternion_wxyz']
    if len(q)!=4 or any(type(x)not in (int,float) or not math.isfinite(x) for x in q):raise ValueError('RESET_QUATERNION')
    # q and -q describe the same attitude; compare both without normalizing data.
    if min(max(abs(a-b) for a,b in zip(q,expected)),max(abs(a+b) for a,b in zip(q,expected)))>quaternion_atol:
        raise ValueError('RESET_QUATERNION_MISMATCH')
    for field in ('root_linear_velocity_w_m_s','root_angular_velocity_w_rad_s'):
        if max(abs(x) for x in vector(actual[field]))>velocity_atol:raise ValueError('RESET_VELOCITY_MISMATCH')
    return True


def pulse_force(block,*,lane,physics_tick,mass_kg):
    if type(physics_tick)is not int or physics_tick<0:raise ValueError('PHYSICS_TICK')
    if type(mass_kg)not in (int,float) or not math.isfinite(mass_kg) or mass_kg<=0:raise ValueError('MASS')
    _,direction=lane_role(block,lane)
    active=block['task']=='pulse_hold' and 1000<=physics_tick<1040
    acceleration=block.get('pulse_acceleration_m_s2',0.) if active else 0.
    return tuple(mass_kg*acceleration*x for x in direction)
"""R6 evaluation blocks on the existing authorized H1 backend.

No AppLauncher, checkpoint substitution, permission issuance or old-suite scoring
changes here. Caller loads the exactly authorized model and freezes the protocol.
"""
from pathlib import Path
import torch
from instinctlab.control.lee_velocity_controller import rotate_world_to_body_wxyz
from training_workloads.scale_003.persistence import atomic_json_replace
from .robustness import command,score_block
from .range_archive import RangeArchive
from .robustness_audit import AuditLog,write_block_metadata


def world_command(block,step,reference):
    return torch.tensor([command(block,i,step) for i in range(32)],device=reference.device,dtype=reference.dtype)


def lane_sample(sensor,root,masks,lane,episode,*,time_s):
    return dict(sensor_position_w_m=sensor[lane].detach().cpu().tolist(),
        velocity_w_m_s=root[lane,7:10].detach().cpu().tolist(),episode_id=episode,time_s=time_s,
        collision=bool(masks['collision'][lane,0]),
        height_violation=bool(masks['below_height'][lane,0] or masks['above_height'][lane,0]),missing=False)


def evaluate_block(backend,block,*,run_id,seed,split,expected_mass_kg,range_quota_bytes,audit_quota_bytes):
    if not isinstance(run_id,str) or not run_id or type(seed)is not int or split not in ('development','final'):
        raise ValueError('explicit R6 run/random-stream identity required')
    if block['lanes']!=32 or block['steps']!=(200 if block['task']=='reverse' else 330):
        raise ValueError('R6 evaluation block denominator')
    if not isinstance(block['id'],str) or not block['id'] or any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' for c in block['id']):
        raise ValueError('R6 block identifier')
    if backend.trainer is None:raise ValueError('load authorized checkpoint before R6 evaluation')
    env=backend.environment;budgets=backend.authorization['budgets'];counters=backend.counters
    folder=Path(backend.output)/'r6'/block['id'];folder.mkdir(parents=True,exist_ok=False)
    counts={'force':0,'reset':0}
    def record(kind,row):
        audit.append(kind,row);counts[kind]+=1
    with AuditLog(folder/'audit.bin',run_id=run_id,block_id=block['id'],maximum_bytes=audit_quota_bytes) as audit, \
         RangeArchive(folder/'measurements.bin',run_id=run_id,block_id=block['id'],maximum_bytes=range_quota_bytes) as archive:
        audit.append('identity',dict(block=block,seed=seed,split=split,expected_mass_kg=expected_mass_kg,
            actor_mode='deterministic_mean',command_frame='world converted at actual observation boundary',
            sensor_frames=block['steps']+1,physics_ticks=block['steps']*20))
        def measurement(sequence,frame):
            if sequence!=archive.frames:raise ValueError('R6 archive sequence drift')
            archive.append(frame)
        env.set_h1_evaluation_case(None)
        env.configure_r6_physics(block=block,seed=seed,split=split,reset_sink=lambda row:record('reset',row),
            force_sink=lambda row:record('force',row),expected_mass_kg=expected_mass_kg)
        env.configure_r6_measurements(seed=seed,stream_id=split+'/'+block['id'],sigma_m=block['noise_std_m'],
            delay_cycles=block['delay_cycles'],drop_steps=block.get('drop_policy_steps',[]),
            frame_limit=block['steps']+1,audit_sink=measurement)
        reference=env._command_b
        env.set_h1_initial_command(torch.zeros_like(reference),0)
        env.stage_r6_world_command(world_command(block,0,reference))
        backend.resource_check('before_r6_reset',counters.explicit_resets+1)
        observation,_=backend._preserving_reset(seed=seed)
        env._refresh_task_snapshot()
        sensor=env._evaluation_ray_snapshot.ray_starts_w[:,0].detach().clone()
        root=env._robot.data.root_state_w.detach().clone()
        masks=env._task.termination.masks
        traces=[dict(schema_version='r6-motion-trace/1',run_id=run_id,block_id=block['id'],lane=i,
            env_origin_w_m=env.scene.env_origins[i].detach().cpu().tolist(),
            initial=lane_sample(sensor,root,masks,i,0,time_s=0.),rows=[]) for i in range(32)]
        audit.append('initial',dict(root_state_w=root,sensor_position_w_m=sensor,
            env_origins_w_m=env.scene.env_origins,lanes=[t['initial'] for t in traces]))
        episodes=[0]*32
        backend.trainer.actor.eval()
        for step in range(block['steps']):
            backend.resource_check('before_r6_policy_step',step)
            counters.require_step_capacity(kind='nontraining',lanes=32,maximum=budgets['nontraining_transitions'])
            counters.require_reset_capacity(automatic=True,lanes=32,maximum=budgets['automatic_resets'])
            current=world_command(block,step,reference);following=world_command(block,step+1,reference)
            attitude=env._robot.data.root_state_w[:,3:7]
            body=rotate_world_to_body_wxyz(attitude,current)
            if not torch.allclose(observation['policy']['state_vec'][:,45:48],body,atol=1e-6,rtol=0) or not torch.equal(observation['policy']['state_vec'][:,45:48],env._command_b):
                raise ValueError('R6 actor/internal/world command mismatch')
            env.stage_r6_world_command(following)
            env.prepare_h1_step(global_policy_step=step,command_b=env._command_b,
                next_command_b=rotate_world_to_body_wxyz(attitude,following))
            with torch.no_grad():action=backend.trainer.actor(observation['policy']).mean_action.detach()
            counters.attempt_step()
            audit.append('step_attempt',dict(policy_step=step,counters=counters.snapshot(),
                command_w_m_s=current,command_b_m_s=body,attitude_wxyz=attitude,action=action,
                input_measurement_sequence=step))
            observation,_,terminated,truncated,extras=env.step(action)
            counters.complete_step(32,kind='nontraining')
            reset=(terminated|truncated).detach().cpu().reshape(-1)
            if reset.shape!=(32,):raise ValueError('R6 reset denominator')
            counters.reserve_reset(automatic=True,lanes=int(reset.sum()),maximum=budgets['automatic_resets'])
            pre=extras['pre_reset'];source=extras['evaluation_ray_source'];root=pre['root_state_w']
            sensor=source['ray_starts_w'][:,0];masks=pre['task']['termination']['masks']
            samples=[]
            for lane in range(32):
                # A reset on the last sample also fails; no last-step omission.
                episodes[lane]+=int(reset[lane])
                row=lane_sample(sensor,root,masks,lane,episodes[lane],time_s=(step+1)*.1)
                row.update(policy_step=step,command_w_m_s=current[lane].detach().cpu().tolist())
                traces[lane]['rows'].append(row);samples.append(row)
            audit.append('step_complete',dict(policy_step=step,counters=counters.snapshot(),lanes=samples,
                root_state_w=root,reset_mask=reset,control=pre['control'],reward_diagnostics=extras['reward_diagnostics'],
                output_measurement_sequence=step+1,timing='action_t/command_t before physics; root, source and reward diagnostics are pre-reset t+1; delivery archive t+1 may reflect reset'))
        physics_completion=env.finish_r6_physics();env.finish_r6_measurements()
        if archive.frames!=block['steps']+1 or counts['force']!=block['steps']*20 or counts['reset']<32:
            raise ValueError('R6 missing measurement/reset/force evidence')
        result=score_block(block,traces,run_id=run_id)
        summary=dict(schema_version='r6-block-result/1',run_id=run_id,block_id=block['id'],seed=seed,split=split,
            scoring=result,counters=counters.snapshot(),measurement_frames=archive.frames,audit_records=audit.records,
            force_records=counts['force'],reset_records=counts['reset'],measurement_bytes=archive.written,audit_bytes=audit.written,
            physics_completion=physics_completion,
            evidence_status='COMPLETE_BLOCK_REQUIRES_INDEPENDENT_REPLAY',scientific_acceptance=False)
    # Preserve the complete replayable lane records separately for the pure scorer.
    write_block_metadata(folder,traces,summary)
    return summary

"""R6 range-frame impairment before the shared actor/ICS history interface.

Dormant until explicitly constructed by a registered R6 workload. This module
accepts only measured ranges, validity and time. Clean copies are audit output,
never inputs to the actor/control history. It does not alter the actor schema.
"""
import hashlib
import math
import torch


class RangeDelivery:
    def __init__(self, *, lanes, rays, seed, stream_id, sigma_m=0., delay_cycles=0,
                 device='cpu', dtype=torch.float32):
        if type(lanes) is not int or lanes<=0 or type(rays) is not int or rays<=0:
            raise ValueError('positive tensor dimensions required')
        if type(seed) is not int or not isinstance(stream_id,str) or not stream_id:
            raise ValueError('explicit random stream identity required')
        if type(sigma_m) not in (int,float) or not math.isfinite(sigma_m) or not 0<=sigma_m<=.03:
            raise ValueError('unregistered noise range')
        if type(delay_cycles) is not int or delay_cycles not in (0,1):
            raise ValueError('unregistered delay')
        if dtype not in (torch.float32,torch.float64): raise ValueError('floating dtype required')
        self.lanes,self.rays=lanes,rays
        self.sigma,self.delay=float(sigma_m),delay_cycles
        self.device,self.dtype=torch.device(device),dtype
        self.generators=[];self.streams=[]
        for lane in range(lanes):
            # A single CPU algorithm is replayable without CUDA and independent
            # of the device running physics. This is a new stream identity.
            payload=f'R6/range-noise/cpu-v1/{seed}/{stream_id}/{lane}'.encode()
            digest=hashlib.sha256(payload).hexdigest()
            generator=torch.Generator(device='cpu')
            generator.manual_seed(int(digest[:16],16)%(2**63))
            self.generators.append(generator);self.streams.append(digest)
        self.pending=self._empty();self.last=self._empty()
        self.last_time=torch.full((lanes,1),-1.,device=self.device,dtype=dtype)

    def _empty(self):
        return dict(ranges=torch.full((self.lanes,self.rays),40.,device=self.device,dtype=self.dtype),
                    valid=torch.zeros((self.lanes,self.rays),device=self.device,dtype=torch.bool),
                    time=torch.zeros((self.lanes,1),device=self.device,dtype=self.dtype),
                    available=torch.zeros((self.lanes,1),device=self.device,dtype=torch.bool))

    def reset(self, indices):
        if not isinstance(indices,torch.Tensor) or indices.dtype!=torch.long or indices.ndim!=1 or indices.device!=self.device:
            raise ValueError('reset indices must be device long vector')
        if bool(((indices<0)|(indices>=self.lanes)).any()): raise ValueError('reset index range')
        for frame in (self.pending,self.last):
            frame['ranges'][indices]=40.;frame['valid'][indices]=False
            frame['time'][indices]=0.;frame['available'][indices]=False
        self.last_time[indices]=-1.
        # Noise streams continue across physical resets; reset does not silently
        # replay the same noise. Full RNG states belong in the experiment record.

    def rng_states(self):
        return [g.get_state().clone() for g in self.generators]

    def deliver(self, ranges_m, validity, acquisition_time_s, drop):
        shape=(self.lanes,self.rays)
        for value,expected,dtype in ((ranges_m,shape,self.dtype),(validity,shape,torch.bool),
                                     (acquisition_time_s,(self.lanes,1),self.dtype),
                                     (drop,(self.lanes,1),torch.bool)):
            if not isinstance(value,torch.Tensor) or value.shape!=expected or value.dtype!=dtype or value.device!=self.device:
                raise ValueError('measurement shape/device/dtype mismatch')
        if not bool(torch.isfinite(ranges_m).all()) or not bool(torch.isfinite(acquisition_time_s).all()):
            raise ValueError('nonfinite producer input')
        if bool((acquisition_time_s<0).any()) or bool((acquisition_time_s<=self.last_time).any()):
            raise ValueError('acquisition timestamp must advance; reset lane explicitly')
        if bool(((ranges_m<.1)|(ranges_m>40.)).any()):
            raise ValueError('producer range outside approved bounds')
        if bool(((~validity)&(ranges_m!=40.)).any()):
            raise ValueError('invalid beam must retain exact 40m fill')
        noisy=ranges_m.clone()
        if self.sigma:
            noisy=ranges_m.detach().cpu().clone()
            cpu_validity=validity.detach().cpu()
            for lane,generator in enumerate(self.generators):
                mask=cpu_validity[lane]
                # Draw by acquisition/lane/beam, never by a policy-dependent
                # validity mask. Paired policies therefore receive the same
                # noise on shared beams and keep identical subsequent streams.
                noise=torch.randn((self.rays,),device='cpu',dtype=self.dtype,generator=generator)
                noisy[lane,mask]=(noisy[lane,mask]+noise[mask].clamp(-3.,3.)*self.sigma).clamp(.1,40.)
            noisy=noisy.to(self.device)
        acquired=dict(ranges=noisy,valid=validity.clone(),time=acquisition_time_s.clone(),
                      available=torch.ones((self.lanes,1),device=self.device,dtype=torch.bool))
        candidate=acquired if self.delay==0 else self.pending
        delivered={key:torch.where(drop,self.last[key],value).clone() for key,value in candidate.items()}
        self.pending={k:v.clone() for k,v in acquired.items()}
        self.last={k:v.clone() for k,v in delivered.items()}
        self.last_time.copy_(acquisition_time_s)
        return dict(clean_ranges=ranges_m.clone(),clean_validity=validity.clone(),
                    delivered_ranges=delivered['ranges'],delivered_validity=delivered['valid'],
                    acquisition_time=delivered['time'],delivery_time=acquisition_time_s.clone(),
                    frame_age=acquisition_time_s-delivered['time'],drop=drop.clone(),
                    frame_available=delivered['available'],noise_rng_identity=list(self.streams))
"""Opt-in R6 measurement wiring; no simulator imports or privileged inputs.

The workload installs one finite block and resets before taking observations.
Only ranges, validity and sensor time pass to history; clean frames go to the
explicit audit sink. ICS continues to extract the same history as the actor.
"""
import torch
from .actor import RAY_COUNT
from .robustness import RangeDelivery


class R6MeasurementMixin:
    def configure_r6_measurements(self, *, seed, stream_id, sigma_m, delay_cycles,
                                  drop_steps, frame_limit, audit_sink):
        if getattr(self,'_r6_measurements',None) is not None:
            raise RuntimeError('finish the existing R6 measurement block first')
        if getattr(self,'_h1_evaluation_case',None) is not None:
            raise ValueError('original suite cannot use R6 impairment')
        if type(frame_limit)is not int or frame_limit<=0:
            raise ValueError('finite frame limit required, including reset observation')
        if not isinstance(drop_steps,(list,tuple)) or any(type(s)is not int or not 0<=s<frame_limit for s in drop_steps):
            raise ValueError('drop indices must refer to registered block observations')
        if len(set(drop_steps))!=len(drop_steps) or any(s+1 in drop_steps for s in drop_steps):
            raise ValueError('only distinct isolated frame drops are registered')
        if not callable(audit_sink):raise TypeError('durable measurement audit sink required')
        chain=RangeDelivery(lanes=self.num_envs,rays=RAY_COUNT,seed=seed,stream_id=stream_id,
            sigma_m=sigma_m,delay_cycles=delay_cycles,device=self._actions.device,dtype=self._actions.dtype)
        self._r6_measurements=dict(chain=chain,drop_steps=frozenset(drop_steps),frame_limit=frame_limit,
            sequence=0,sink=audit_sink,reset_lanes=set(),failed=False)

    def finish_r6_measurements(self):
        block=getattr(self,'_r6_measurements',None)
        if block is None:raise RuntimeError('no active R6 block')
        if block['failed'] or block['sequence']!=block['frame_limit']:
            raise RuntimeError('incomplete R6 measurement block must be preserved')
        self._r6_measurements=None

    def _reset_policy_sensor_frame(self,indices):
        super()._reset_policy_sensor_frame(indices)
        block=getattr(self,'_r6_measurements',None)
        if block is not None:
            block['chain'].reset(indices)
            block['reset_lanes'].update(indices.detach().cpu().tolist())

    def _policy_sensor_frame(self,ranges_m,validity,policy_time):
        block=getattr(self,'_r6_measurements',None)
        if block is None:return super()._policy_sensor_frame(ranges_m,validity,policy_time)
        if getattr(self,'_h1_evaluation_case',None) is not None:
            raise RuntimeError('R6 block cannot contaminate original suite')
        if block['failed']:raise RuntimeError('failed measurement block cannot continue')
        if block['reset_lanes']!=set(range(self.num_envs)):
            raise RuntimeError('reset all lanes after installing R6 measurement block')
        if block['sequence']>=block['frame_limit']:raise RuntimeError('R6 measurement frame quota')
        drop=torch.full((self.num_envs,1),block['sequence'] in block['drop_steps'],
                        device=policy_time.device,dtype=torch.bool)
        try:
            audit=block['chain'].deliver(ranges_m,validity,policy_time,drop)
            # Sink cannot modify the measurement passed into actor/ICS history.
            frame=tuple(audit[k].clone() for k in ('delivered_ranges','delivered_validity','acquisition_time'))
            block['sink'](block['sequence'],audit)
        except BaseException:
            block['failed']=True
            raise
        block['sequence']+=1
        return frame
"""Opt-in R6 privileged reset/disturbance wiring; never actor inputs."""
import copy
import math
import torch
from instinctlab.control.lee_velocity_controller import quaternion_to_rotation_matrix_wxyz
from instinctlab.control.lee_velocity_controller import rotate_world_to_body_wxyz
from training_workloads.unified_h1.robustness_scenarios import reset_spec,verify_reset


def distributed_pulse(masses,body_quaternions,acceleration_world,rotor_forces,rotor_torques):
    """Mass-proportional force at each body COM: zero net added COM torque.

    Isaac's public setter takes local link-frame vectors and applies them at
    body COM when positions=None. Preserve the existing rotor torque buffers.
    """
    n=masses.shape[0]
    if masses.shape!=(n,5) or body_quaternions.shape!=(n,5,4) or acceleration_world.shape!=(n,3):
        raise ValueError('R6 public plant tensor shape')
    if rotor_forces.shape!=(n,5,3) or rotor_torques.shape!=rotor_forces.shape:
        raise ValueError('R6 rotor wrench tensor shape')
    values=(masses,body_quaternions,acceleration_world,rotor_forces,rotor_torques)
    if any(not bool(torch.isfinite(x).all()) for x in values) or bool((masses<=0).any()):
        raise ValueError('R6 finite positive measured plant required')
    if any(x.device!=rotor_forces.device or x.dtype!=rotor_forces.dtype for x in values):
        raise ValueError('R6 force dtype/device mismatch')
    norms=torch.linalg.vector_norm(body_quaternions,dim=-1,keepdim=True)
    if bool(((norms-1).abs()>1e-5).any()):raise ValueError('R6 body quaternion norm')
    rotation=quaternion_to_rotation_matrix_wxyz((body_quaternions/norms).reshape(-1,4)).reshape(n,5,3,3)
    world=masses[:,:,None]*acceleration_world[:,None,:]
    local=torch.matmul(rotation.transpose(-1,-2),world.unsqueeze(-1)).squeeze(-1)
    return rotor_forces+local,rotor_torques.clone(),world,local


class R6PhysicsMixin:
    def configure_r6_physics(self, *, block, seed, split, reset_sink, force_sink,expected_mass_kg):
        if getattr(self,'_r6_physics',None) is not None:raise RuntimeError('R6 physics already active')
        if self.num_envs!=32 or getattr(self,'_h1_evaluation_case',None) is not None:
            raise ValueError('R6 requires32 lanes and separate original suite')
        if getattr(self,'_enhanced_b0_active',False):raise ValueError('R6/enhanced-B0 conflict')
        if not callable(reset_sink) or not callable(force_sink):raise TypeError('R6 audit sinks required')
        if type(block.get('steps'))is not int or block['steps']<=0:raise ValueError('finite R6 step budget required')
        acceleration=block.get('pulse_acceleration_m_s2',0.)
        if acceleration not in (0.,.5,1.) or (acceleration!=0 and block['task']!='pulse_hold'):
            raise ValueError('unregistered R6 force level')
        if type(expected_mass_kg)not in (int,float) or not 0<expected_mass_kg<100:
            raise ValueError('pinned baseline total mass required')
        specs=[reset_spec(block,seed=seed,split=split,lane=i,mount_position_m=self.cfg.ray_caster.offset.pos) for i in range(32)]
        self._r6_physics=dict(block=copy.deepcopy(block),specs=specs,reset_sink=reset_sink,force_sink=force_sink,
            pending=set(),ready=set(),ticks=0,last_sim_tick=None,failed=False,expected_mass=float(expected_mass_kg),world_command=None)

    def stage_r6_world_command(self,command):
        """Command for the next observation boundary, not another actor field."""
        state=getattr(self,'_r6_physics',None)
        if state is None or state['failed']:raise RuntimeError('active R6 block required')
        self._validate_h1_command('R6 world command',command)
        if bool((torch.linalg.vector_norm(command,dim=-1)>.300001).any()) or bool(command[:,2].ne(0).any()):
            raise ValueError('R6 low-speed horizontal command boundary')
        state['world_command']=command.detach().clone()

    def _reset_r6_physics(self,indices):
        state=getattr(self,'_r6_physics',None)
        if state is None:return False
        if state['failed']:raise RuntimeError('failed R6 physics block')
        if getattr(self,'_h1_evaluation_case',None) is not None:raise RuntimeError('original suite/R6 reset conflict')
        lanes=indices.detach().cpu().tolist()
        if not lanes:return True
        root=self._robot.data.root_state_w[indices].clone()
        specs=state['specs']
        root[:,:3]=torch.tensor([specs[i]['root_position_local_m'] for i in lanes],device=root.device,dtype=root.dtype)+self.scene.env_origins[indices]
        root[:,3:7]=torch.tensor([specs[i]['root_quaternion_wxyz'] for i in lanes],device=root.device,dtype=root.dtype)
        root[:,7:13]=0.
        state['pending'].update(lanes);state['ready'].difference_update(lanes)
        try:
            self._robot.write_root_pose_to_sim(root[:,:7],indices)
            self._robot.write_root_velocity_to_sim(root[:,7:],indices)
        except BaseException:
            state['failed']=True
            raise
        return True

    def _policy_sensor_frame(self,ranges_m,validity,policy_time):
        state=getattr(self,'_r6_physics',None)
        if state is not None and state['pending']:
            # Called after the actual sensor producer refresh, not from planned
            # coordinates or a cached expected sensor location.
            ray=self._ray_caster.data;root=self._robot.data.root_state_w
            rotation=quaternion_to_rotation_matrix_wxyz(ray.quat_w)
            mount=torch.tensor(self.cfg.ray_caster.offset.pos,device=root.device,dtype=root.dtype)
            sensor=ray.pos_w+torch.matmul(rotation,mount)
            try:
                for lane in sorted(state['pending']):
                    actual=dict(sensor_position_local_m=(sensor[lane]-self.scene.env_origins[lane]).detach().cpu().tolist(),
                        root_position_local_m=(root[lane,:3]-self.scene.env_origins[lane]).detach().cpu().tolist(),
                        root_quaternion_wxyz=root[lane,3:7].detach().cpu().tolist(),
                        root_linear_velocity_w_m_s=root[lane,7:10].detach().cpu().tolist(),
                        root_angular_velocity_w_rad_s=root[lane,10:13].detach().cpu().tolist())
                    # Persist failures as well as successful reset observations.
                    # Float32 world origins can lose more than1e-5m on subtraction.
                    # Bound representational error explicitly, without rounding
                    # observed coordinates or altering geometric safety metrics.
                    magnitude=max(1.,float(root[lane,:3].abs().max()),float(sensor[lane].abs().max()))
                    position_atol=max(1e-5,2*torch.finfo(root.dtype).eps*magnitude)
                    state['reset_sink'](dict(lane=lane,block_tick=state['ticks'],expected=copy.deepcopy(state['specs'][lane]),actual=actual,
                        dtype=str(root.dtype),env_origin_w_m=self.scene.env_origins[lane].detach().cpu().tolist(),
                        root_position_w_m=root[lane,:3].detach().cpu().tolist(),sensor_position_w_m=sensor[lane].detach().cpu().tolist(),
                        position_atol_m=position_atol,position_tolerance_rule='max(1e-5,2*dtype_epsilon*max(1,abs(actual_world_coordinates)))'))
                    verify_reset(state['specs'][lane],actual,position_atol=position_atol)
                state['ready'].update(state['pending']);state['pending'].clear()
            except BaseException:
                state['failed']=True
                raise
        if state is not None and state['world_command'] is not None:
            # Rewards already used c_t. Convert c_(t+1) with actual t+1 attitude
            # before history.update, so both current and retained history agree.
            self._command_b.copy_(rotate_world_to_body_wxyz(self._robot.data.root_state_w[:,3:7],state['world_command']))
        return super()._policy_sensor_frame(ranges_m,validity,policy_time)

    def _apply_external_disturbance(self):
        super()._apply_external_disturbance()
        state=getattr(self,'_r6_physics',None)
        if state is None:return
        if state['failed'] or state['ready']!=set(range(32)) or state['pending']:
            raise RuntimeError('R6 reset must be observed before physics')
        tick=state['ticks'];sim_tick=self.sim.current_time_step_index
        physics_dt=float(self.sim.get_physics_dt())
        if not math.isfinite(physics_dt) or abs(physics_dt-.005)>1e-12:raise RuntimeError('R6 actual physics dt differs')
        if type(sim_tick)is not int or (state['last_sim_tick'] is not None and sim_tick!=state['last_sim_tick']+1):
            raise RuntimeError('R6 actual physics clock discontinuity')
        if tick>=state['block']['steps']*20:raise RuntimeError('R6 physics tick quota')
        try:
            mass=self._robot.root_physx_view.get_masses().to(self._wrench.forces_body_n)
            if bool((mass.sum(dim=1)-state['expected_mass']).abs().gt(1e-5).any()):
                raise RuntimeError('R6 measured mass differs from pinned baseline')
            q=self._robot.data.body_link_state_w[:,:,3:7].to(mass)
            directions=torch.tensor([s['direction_world'] for s in state['specs']],device=mass.device,dtype=mass.dtype)
            active=state['block']['task']=='pulse_hold' and 1000<=tick<1040
            acceleration=directions*(state['block'].get('pulse_acceleration_m_s2',0.) if active else 0.)
            forces,torques,world,local=distributed_pulse(mass,q,acceleration,self._wrench.forces_body_n,self._wrench.torques_body_nm)
            if active:self._robot.set_external_force_and_torque(forces,torques,is_global=False)
            # Setter stages buffers; physics application is verified separately
            # from the subsequent trajectory and actual simulator tick audit.
            state['force_sink'](dict(block_tick=tick,sim_tick=sim_tick,active=active,
                physics_dt_s=physics_dt,dtype=str(mass.dtype),body_quaternion_wxyz=q.detach().clone(),
                rotor_forces_local_n=self._wrench.forces_body_n.detach().clone(),
                rotor_torques_local_nm=self._wrench.torques_body_nm.detach().clone(),
                mass_kg=mass.detach().clone(),additional_world_n=world.detach().clone(),
                additional_local_n=local.detach().clone(),staged_forces_local_n=forces.detach().clone(),
                staged_torques_local_nm=torques.detach().clone()))
        except BaseException:
            state['failed']=True
            raise
        state['last_sim_tick']=sim_tick;state['ticks']+=1

    def finish_r6_physics(self):
        state=getattr(self,'_r6_physics',None)
        if state is None or state['failed'] or state['pending'] or state['ticks']!=state['block']['steps']*20:
            raise RuntimeError('incomplete R6 physics block')
        if state['last_sim_tick'] is None or self.sim.current_time_step_index!=state['last_sim_tick']+1:
            raise RuntimeError('last R6 staged wrench has no completed physics tick')
        completion=dict(block_ticks=state['ticks'],last_staged_sim_tick=state['last_sim_tick'],
            completed_sim_tick=self.sim.current_time_step_index,physics_dt_s=float(self.sim.get_physics_dt()),
            evidence_status='STAGING_AND_CLOCK_ONLY_NOT_INTEGRATION_PROOF')
        self._r6_physics=None
        return completion

"""Bounded lossless R6 reset/physics/motion records, independent per-record zlib."""
from pathlib import Path
import hashlib
import json
import os
import struct
import zlib
from .logging import _jsonable
from training_workloads.scale_003.persistence import reserve_output_bytes
from .force_archive import MAGIC,SHAPES,encode_force,decode_force

BLOCK_METADATA_CAP_BYTES=16*1024**2


def write_block_metadata(folder,traces,summary):
    """Bound both complete replay artifacts before writing either one."""
    from training_workloads.scale_003.config import canonical_bytes
    from training_workloads.scale_003.persistence import atomic_json_replace
    size=sum(len(canonical_bytes(value)) for value in (traces,summary))
    if size>BLOCK_METADATA_CAP_BYTES:raise ValueError('R6_BLOCK_METADATA_QUOTA_BEFORE_WRITE')
    atomic_json_replace(folder,'motion_traces.json',traces)
    atomic_json_replace(folder,'result.json',summary)
    return size


HEADER=struct.Struct('<II32s')
MAX_RECORD=8*1024**2


class AuditLog:
    def __init__(self,path,*,run_id,block_id,maximum_bytes):
        if type(maximum_bytes)is not int or maximum_bytes<=0:raise ValueError('AUDIT_QUOTA')
        self.path=Path(path);self.run_id=run_id;self.block_id=block_id;self.maximum=maximum_bytes
        self.written=0;self.records=0;self.failed=False;self.stream=self.path.open('xb')
        fd=os.open(self.path.parent,os.O_DIRECTORY)
        try:os.fsync(fd)
        finally:os.close(fd)
    def append(self,kind,payload):
        if self.failed:raise ValueError('AUDIT_PREVIOUS_FAILURE')
        row=dict(schema_version='r6-audit/1',run_id=self.run_id,block_id=self.block_id,
            sequence=self.records,kind=kind,payload=payload)
        if kind=='force' and all(k in payload for k in SHAPES):
            raw=encode_force(row)
        else:
            raw=json.dumps(_jsonable(row),sort_keys=True,separators=(',',':'),allow_nan=False).encode()
        if len(raw)>MAX_RECORD:raise ValueError('AUDIT_RECORD_BOUND')
        compressed=zlib.compress(raw,3)
        record=HEADER.pack(len(compressed),len(raw),hashlib.sha256(raw).digest())+compressed
        if self.written+len(record)>self.maximum:raise ValueError('AUDIT_QUOTA_BEFORE_WRITE')
        reserve_output_bytes(self.path,len(record))
        try:
            self.stream.write(record);self.stream.flush();os.fsync(self.stream.fileno())
        except BaseException:self.failed=True;raise
        self.written+=len(record);self.records+=1
    def close(self):self.stream.close()
    def __enter__(self):return self
    def __exit__(self,*args):self.close()


def read_audit(path,*,run_id,block_id,expected_records):
    if type(expected_records)is not int or expected_records<=0:raise ValueError('AUDIT_EXPECTED_COUNT')
    with Path(path).open('rb') as stream:
        for sequence in range(expected_records):
            prefix=stream.read(HEADER.size)
            if len(prefix)!=HEADER.size:raise ValueError('AUDIT_MISSING_RECORD')
            size,raw_size,digest=HEADER.unpack(prefix)
            if not 0<size<=MAX_RECORD+65536 or not 0<raw_size<=MAX_RECORD:raise ValueError('AUDIT_RECORD_BOUND')
            compressed=stream.read(size)
            if len(compressed)!=size:raise ValueError('AUDIT_TRUNCATED')
            decoder=zlib.decompressobj();raw=decoder.decompress(compressed,raw_size+1)
            if len(raw)!=raw_size or not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:
                raise ValueError('AUDIT_DECOMPRESSION_BOUND')
            if hashlib.sha256(raw).digest()!=digest:raise ValueError('AUDIT_HASH')
            row=decode_force(raw) if raw.startswith(MAGIC) else json.loads(raw)
            if (row['schema_version'],row['run_id'],row['block_id'],row['sequence'])!=('r6-audit/1',run_id,block_id,sequence):
                raise ValueError('AUDIT_IDENTITY')
            yield row
        if stream.read(1):raise ValueError('AUDIT_EXTRA_RECORDS')
"""Streaming CPU verification of archived delivery, not physical sensor truth.

Replays the versioned production impairment algorithm. Independent review must
still validate that algorithm and actor/ICS wiring, reset physics and clocks.
"""
from pathlib import Path
import numpy as np
import torch

from instinctlab.observations.actor import RAY_COUNT
from instinctlab.observations.robustness import RangeDelivery
from .range_archive import read_archive, ARRAY_KEYS
from .robustness_audit import read_audit
from .robustness_analysis import pin


def reset_schedule(path, block, *, run_id, seed, split, expected_records):
    """Extract exact post-step resets; never infer resets from a regressing clock."""
    steps=block['steps']
    if type(expected_records) is not int or not 0<expected_records<=2+32+steps*(20+2+32):
        raise ValueError('AUDIT_RECORD_COUNT_BOUND')
    resets=[torch.ones(32,dtype=torch.bool)]
    attempts=0; completions=0; initial=0; identities=0; forces=0
    for row in read_audit(path,run_id=run_id,block_id=block['id'],expected_records=expected_records):
        payload=row['payload'];kind=row['kind']
        if kind=='identity':
            if row['sequence']!=0 or payload['block']!=block or payload['seed']!=seed or payload['split']!=split:
                raise ValueError('AUDIT_PROTOCOL_IDENTITY')
            identities+=1
        elif kind=='initial':initial+=1
        elif kind=='step_attempt':
            if attempts!=completions or payload['policy_step']!=attempts or payload['input_measurement_sequence']!=attempts:
                raise ValueError('AUDIT_ATTEMPT_ORDER')
            attempts+=1
        elif kind=='step_complete':
            if attempts!=completions+1 or payload['policy_step']!=completions or payload['output_measurement_sequence']!=completions+1:
                raise ValueError('AUDIT_COMPLETION_ORDER')
            mask=payload['reset_mask']
            if not isinstance(mask,list) or len(mask)!=32 or any(type(v) is not bool for v in mask):
                raise ValueError('AUDIT_RESET_MASK')
            resets.append(torch.tensor(mask,dtype=torch.bool));completions+=1
        elif kind=='force':forces+=1
        elif kind!='reset':raise ValueError('AUDIT_UNKNOWN_KIND')
    if identities!=1 or initial!=1 or attempts!=steps or completions!=steps or forces!=steps*20:
        raise ValueError('AUDIT_COVERAGE')
    return resets


def replay_delivery(path, block, *, run_id, seed, split, resets, expected_rays=RAY_COUNT):
    if block['lanes']!=32 or len(resets)!=block['steps']+1 or split not in ('development','final'):
        raise ValueError('MEASUREMENT_DENOMINATOR')
    path=Path(path)
    if path.is_symlink() or path.absolute()!=path.resolve():raise ValueError('MEASUREMENT_PATH_ALIAS')
    before=pin(path);chain=None;count=0;reset_count=0
    for sequence, frame in enumerate(read_archive(path,run_id=run_id,block_id=block['id'],expected_frames=block['steps']+1)):
        clean=frame['clean_ranges']
        if clean.shape!=(32,expected_rays) or clean.dtype not in (np.dtype('float32'),np.dtype('float64')):
            raise ValueError('MEASUREMENT_BEAM_DENOMINATOR')
        if chain is None:
            chain=RangeDelivery(lanes=32,rays=expected_rays,seed=seed,stream_id=split+'/'+block['id'],
                sigma_m=block['noise_std_m'],delay_cycles=block['delay_cycles'],dtype=torch.from_numpy(clean).dtype)
        mask=resets[sequence]
        if not isinstance(mask,torch.Tensor) or mask.shape!=(32,) or mask.dtype!=torch.bool or mask.device.type!='cpu':
            raise ValueError('MEASUREMENT_RESET_MASK')
        if sequence==0 and not bool(mask.all()):raise ValueError('MEASUREMENT_INITIAL_RESET')
        indices=mask.nonzero().flatten();chain.reset(indices);reset_count+=len(indices)
        drop=torch.full((32,1),sequence in block.get('drop_policy_steps',[]),dtype=torch.bool)
        expected=chain.deliver(torch.from_numpy(clean),torch.from_numpy(frame['clean_validity']),
            torch.from_numpy(frame['delivery_time']),drop)
        if frame['noise_rng_identity']!=expected['noise_rng_identity']:
            raise ValueError(f'MEASUREMENT_RNG_IDENTITY:{sequence}')
        for field in ARRAY_KEYS:
            actual=frame[field];wanted=expected[field].numpy()
            if actual.dtype!=wanted.dtype or actual.shape!=wanted.shape or actual.tobytes()!=wanted.tobytes():
                raise ValueError(f'MEASUREMENT_DELIVERY_MISMATCH:{sequence}:{field}')
        count+=1
    if pin(path)!=before:raise ValueError('MEASUREMENT_INPUT_CHANGED')
    return dict(schema_version='r6-measurement-replay/1',archive=before,block_id=block['id'],run_id=run_id,
        seed=seed,split=split,frames=count,lanes=32,rays=expected_rays,reset_lane_events=reset_count,
        bit_exact_delivery=True,noise_algorithm='R6/range-noise/cpu-v1',scientific_acceptance=False,
        limitation='Replays production impairment only; sensor truth, reset/physics clocks, actor/ICS wiring and independent review remain required')


def replay_block_measurements(folder,block,*,run_id,seed,split,result):
    folder=Path(folder);audit=folder/'audit.bin';before=pin(audit)
    resets=reset_schedule(audit,block,run_id=run_id,seed=seed,split=split,expected_records=result['audit_records'])
    replay=replay_delivery(folder/'measurements.bin',block,run_id=run_id,seed=seed,split=split,resets=resets)
    if pin(audit)!=before:raise ValueError('MEASUREMENT_AUDIT_CHANGED')
    if result['measurement_frames']!=replay['frames'] or result['measurement_bytes']!=replay['archive']['bytes']:
        raise ValueError('MEASUREMENT_RESULT_COUNTS')
    replay['audit']=before
    return replay
"""CPU numeric reconstruction of recorded wrench staging and reset evidence.

Uses NumPy quaternion algebra, not production distributed_pulse. Passing does
not prove that Isaac integrated the staged forces or that sensor truth is valid.
"""
import math
import ast
from pathlib import Path
import numpy as np
from .robustness import lane_role
from .robustness_scenarios import reset_spec,verify_reset
from .robustness_audit import read_audit
from .robustness_analysis import pin


def verified_mount(protocol):
    binding=protocol['physics_replay']['mount_source'];path=Path(binding['path'])
    actual=pin(path)
    if {k:actual[k] for k in ('path','sha256')}!=binding:raise ValueError('PHYSICS_MOUNT_SOURCE_HASH')
    values=[ast.literal_eval(node.value) for node in ast.parse(path.read_text()).body
        if isinstance(node,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='MOUNT_POSITION_M' for t in node.targets)]
    if len(values)!=1 or list(values[0])!=protocol['physics_replay']['mount_position_m']:
        raise ValueError('PHYSICS_MOUNT_SOURCE_VALUE')
    return actual


def array(value,shape):
    result=np.asarray(value,dtype=np.float64)
    if result.shape!=shape or not np.isfinite(result).all():raise ValueError('PHYSICS_ARRAY_SHAPE_OR_FINITE')
    return result


def epsilon(row):
    if row.get('dtype') not in ('torch.float32','torch.float64'):raise ValueError('PHYSICS_DTYPE')
    return np.finfo(np.float32 if row['dtype']=='torch.float32' else np.float64).eps


def close(actual,expected,eps,name):
    # Arithmetic roundoff only, never a relaxation of motion/safety thresholds.
    bound=16*eps*max(1.,float(np.max(np.abs(expected))))
    if np.max(np.abs(actual-expected))>bound:raise ValueError('PHYSICS_MISMATCH:'+name)


def verify_force(row,block,*,expected_tick,previous_sim_tick,expected_mass_kg):
    if type(expected_mass_kg) not in (int,float) or not math.isfinite(expected_mass_kg) or expected_mass_kg<=0:
        raise ValueError('PHYSICS_EXPECTED_MASS')
    eps=epsilon(row)
    if type(row['block_tick']) is not int or row['block_tick']!=expected_tick:
        raise ValueError('PHYSICS_BLOCK_TICK')
    sim=row['sim_tick']
    if type(sim) is not int or sim<0 or (previous_sim_tick is not None and sim!=previous_sim_tick+1):
        raise ValueError('PHYSICS_SIM_TICK')
    dt=row['physics_dt_s']
    if type(dt) not in (int,float) or not math.isfinite(dt) or abs(dt-.005)>1e-12:raise ValueError('PHYSICS_DT')
    active=block['task']=='pulse_hold' and 1000<=expected_tick<1040
    if type(row['active']) is not bool or row['active']!=active:raise ValueError('PHYSICS_PULSE_WINDOW')
    masses=array(row['mass_kg'],(32,5))
    if (masses<=0).any() or (np.abs(masses.sum(axis=1)-expected_mass_kg)>1e-5).any():raise ValueError('PHYSICS_MASS')
    quats=array(row['body_quaternion_wxyz'],(32,5,4));norm=np.linalg.norm(quats,axis=-1)
    if (np.abs(norm-1)>1e-5).any():raise ValueError('PHYSICS_QUATERNION')
    quats=quats/norm[:,:,None];w,x,y,z=np.moveaxis(quats,-1,0)
    rotation=np.stack((1-2*(y*y+z*z),2*(x*y-w*z),2*(x*z+w*y),
        2*(x*y+w*z),1-2*(x*x+z*z),2*(y*z-w*x),
        2*(x*z-w*y),2*(y*z+w*x),1-2*(x*x+y*y)),axis=-1).reshape(32,5,3,3)
    directions=np.asarray([lane_role(block,i)[1] for i in range(32)])
    acceleration=directions*(block.get('pulse_acceleration_m_s2',0.) if active else 0.)
    world=masses[:,:,None]*acceleration[:,None,:]
    local=np.einsum('nbji,nbj->nbi',rotation,world)
    recorded_world=array(row['additional_world_n'],(32,5,3));recorded_local=array(row['additional_local_n'],(32,5,3))
    rotor=array(row['rotor_forces_local_n'],(32,5,3));torque=array(row['rotor_torques_local_nm'],(32,5,3))
    staged=array(row['staged_forces_local_n'],(32,5,3));staged_torque=array(row['staged_torques_local_nm'],(32,5,3))
    close(recorded_world,world,eps,'world_force');close(recorded_local,local,eps,'local_force')
    close(staged,rotor+recorded_local,eps,'rotor_addition')
    if not np.array_equal(staged_torque,torque):raise ValueError('PHYSICS_ROTOR_TORQUE_CHANGED')
    if not active and (np.any(recorded_world) or np.any(recorded_local) or not np.array_equal(staged,rotor)):
        raise ValueError('PHYSICS_FORCE_NOT_WITHDRAWN')
    return sim,recorded_world.sum(axis=1)*dt


def verify_reset_record(row,block,*,seed,split,mount_position_m):
    lane=row['lane'];eps=epsilon(row)
    if type(lane) is not int or not 0<=lane<32:raise ValueError('PHYSICS_RESET_LANE')
    expected=reset_spec(block,seed=seed,split=split,lane=lane,mount_position_m=mount_position_m)
    if row['expected']!=expected:raise ValueError('PHYSICS_RESET_SPEC')
    origin=array(row['env_origin_w_m'],(3,));root=array(row['root_position_w_m'],(3,));sensor=array(row['sensor_position_w_m'],(3,))
    tolerance=max(1e-5,2*eps*max(1.,float(np.max(np.abs(root))),float(np.max(np.abs(sensor)))))
    if row['position_atol_m']!=tolerance:raise ValueError('PHYSICS_RESET_TOLERANCE')
    actual=row['actual']
    dtype=np.float32 if row['dtype']=='torch.float32' else np.float64
    for name,world in [('root_position_local_m',root),('sensor_position_local_m',sensor)]:
        local=(world.astype(dtype)-origin.astype(dtype)).astype(np.float64)
        if not np.array_equal(array(actual[name],(3,)),local):raise ValueError('PHYSICS_RESET_WORLD_LOCAL')
    verify_reset(expected,actual,position_atol=tolerance)
    return lane


def replay_staging(path,block,*,run_id,seed,split,expected_records,expected_mass_kg,mount_position_m,completion):
    before=pin(path);ticks=0;last=None;resets=0;initial=set();impulse=np.zeros((32,3))
    if type(expected_records) is not int or not 0<expected_records<=34+block['steps']*54:
        raise ValueError('PHYSICS_RECORD_BOUND')
    for record in read_audit(path,run_id=run_id,block_id=block['id'],expected_records=expected_records):
        row=record['payload']
        if record['kind']=='reset':
            lane=verify_reset_record(row,block,seed=seed,split=split,mount_position_m=mount_position_m)
            if row['block_tick']!=ticks:raise ValueError('PHYSICS_RESET_TICK')
            if ticks==0:
                if lane in initial:raise ValueError('PHYSICS_DUPLICATE_INITIAL_RESET')
                initial.add(lane)
            resets+=1
        elif record['kind']=='force':
            if initial!=set(range(32)):raise ValueError('PHYSICS_INITIAL_RESET_COVERAGE')
            last,delta=verify_force(row,block,expected_tick=ticks,previous_sim_tick=last,expected_mass_kg=expected_mass_kg)
            impulse+=delta;ticks+=1
    if ticks!=block['steps']*20:raise ValueError('PHYSICS_FORCE_COVERAGE')
    if (completion.get('block_ticks')!=ticks or completion.get('last_staged_sim_tick')!=last
            or completion.get('completed_sim_tick')!=last+1 or completion.get('physics_dt_s')!=.005):
        raise ValueError('PHYSICS_FINAL_TICK_NOT_COMPLETED')
    if pin(path)!=before:raise ValueError('PHYSICS_ARCHIVE_CHANGED')
    return dict(schema_version='r6-staging-replay/1',audit=before,force_records=ticks,reset_records=resets,
        staged_impulse_world_ns=impulse.tolist(),staging_reconstructed=True,physical_integration_verified=False,
        scientific_acceptance=False,numeric_tolerance='16*dtype_epsilon*max(1,max(abs(expected))); exact preserved torque/withdrawal')
